<?php require_once 'includes/auth.php';if($_SERVER['REQUEST_METHOD']==='POST'){csrf_check();$name=trim($_POST['name']);$email=trim($_POST['email']);$subject=trim($_POST['subject']);$message=trim($_POST['message']);if($name&&filter_var($email,FILTER_VALIDATE_EMAIL)&&$subject&&$message){$pdo->prepare("INSERT INTO contact_messages(name,email,subject,message) VALUES(?,?,?,?)")->execute([$name,$email,$subject,$message]);flash('success','Thanks — your message has been received.');header('Location: contact.php');exit;}flash('error','Please complete all fields.');}$page_title='Contact';require 'includes/header.php';?><div class="container page-title"><span class="eyebrow">Get in touch</span><h1>Contact us</h1></div><div class="container"><div class="form-card"><form method="post"><input type="hidden" name="csrf" value="<?=csrf_token()?>"><div class="form-grid"><div class="field"><label>Name</label><input class="input" name="name" required></div><div class="field"><label>Email</label><input class="input" type="email" name="email" required></div></div><div class="field"><label>Subject</label><input class="input" name="subject" required></div><div class="field"><label>Message</label><textarea name="message" rows="6" required></textarea></div><button class="btn">Send message</button></form></div></div><?php require 'includes/footer.php';?>
